// The snippet ex2 asks you to predict. The gate runs it from inside a timer
// callback and compares the labels with your answer. Do not edit this file.

export function run(log: (label: string) => void): void {
  process.nextTick(() => {
    log("tick-1");
    queueMicrotask(() => log("micro-from-tick"));
  });
  queueMicrotask(() => {
    log("micro-1");
    process.nextTick(() => log("tick-from-micro"));
  });
  process.nextTick(() => log("tick-2"));
  log("sync");
}
